-- Toutes les fiches de cours Conjugaison CE1 -> CM2 (2026-10-03), une seule transaction.
begin;
-- Fiche Le présent des verbes en -er (CE1) - conjugaison, notion 'present'. Relancer ce script remplace le contenu de la fiche.
insert into contenu_cours (classe, matiere, titre, contenu, statut, notion_id)
select 'ce1', 'conjugaison', 'Le présent des verbes en -er', $fiche$
[titre]Conjuguer un verbe[/titre]
Le verbe change selon [b]qui[/b] fait l'action. Il a deux parties :
[table=3][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]pronom[/b][/color][/center][/cell][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]radical[/b][/color][/center][/cell][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]terminaison[/b][/color][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=26]nous[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=26]dans[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=26][b][color=#C62828]ons[/color][/b][/font_size][/center][/cell][/table]
[cadre]Le [b]radical[/b] ne bouge pas (dans-), la [b]terminaison[/b] change (-e, -es, -ons…).
L'[b]infinitif[/b], c'est le verbe « tout nu » : danser, chanter, parler.[/cadre]
[page]
[titre]Les verbes en -er au présent[/titre]
[table=3][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][/color][/center][/cell][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]danser[/b][/color][/center][/cell][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]parler[/b][/color][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=21][b]je[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=21]dans[b][color=#C62828]e[/color][/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=21]parl[b][color=#C62828]e[/color][/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=21][b]tu[/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=21]dans[b][color=#C62828]es[/color][/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=21]parl[b][color=#C62828]es[/color][/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=21][b]il, elle[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=21]dans[b][color=#C62828]e[/color][/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=21]parl[b][color=#C62828]e[/color][/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=21][b]nous[/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=21]dans[b][color=#C62828]ons[/color][/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=21]parl[b][color=#C62828]ons[/color][/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=21][b]vous[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=21]dans[b][color=#C62828]ez[/color][/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=21]parl[b][color=#C62828]ez[/color][/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=21][b]ils, elles[/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=21]dans[b][color=#C62828]ent[/color][/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=21]parl[b][color=#C62828]ent[/color][/b][/font_size][/center][/cell][/table]
[cadre]Les terminaisons : [b]e, es, e, ons, ez, ent[/b].[/cadre]
[page]
[titre]Les lettres qu'on n'entend pas[/titre]
[cadre]je danse, tu danses, il danse, ils dansent : [b]ça se dit pareil[/b] !
Mais ça ne s'écrit pas pareil :
• avec [b]tu[/b], toujours un [b]s[/b] : tu danse[b]s[/b]
• avec [b]ils / elles[/b], toujours [b]ent[/b] : ils danse[b]nt[/b][/cadre]
[cadre=astuce]Le [b]-ent[/b] de « ils dansent » ne se prononce jamais.[/cadre]
[page]
[titre]Être et avoir[/titre]
Ces deux verbes sont spéciaux : il faut les apprendre par cœur.
[table=3][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][/color][/center][/cell][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]être[/b][/color][/center][/cell][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]avoir[/b][/color][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20][b]je (j')[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]suis[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]j'ai[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=20][b]tu[/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=20]es[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=20]as[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20][b]il, elle[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]est[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]a[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=20][b]nous[/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=20]sommes[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=20]avons[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20][b]vous[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]êtes[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]avez[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=20][b]ils, elles[/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=20]sont[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=20]ont[/font_size][/center][/cell][/table]
[page]
[titre]Je ou j' ?[/titre]
Devant une voyelle ou un h muet, [b]je[/b] devient [b]j'[/b].
[cadre]j'habite · j'essuie · j'écoute · j'ai
mais : je danse · je cache · je tombe[/cadre]
[page]
[titre]-ger et -cer avec nous[/titre]
[table=2][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]-ger : on garde le e[/b][/color][/center][/cell][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]-cer : c devient ç[/b][/color][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]nous plong[b][color=#C62828]e[/color][/b]ons[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]nous ran[b][color=#C62828]ge[/color][/b]ons, nous parta[b][color=#C62828]ge[/color][/b]ons[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]nous lan[b][color=#C62828]ç[/color][/b]ons[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]nous avan[b][color=#C62828]ç[/color][/b]ons[/font_size][/center][/cell][/table]
[cadre=astuce]Sans ce e ou ce ç, on lirait « plongons » (g dur) ou « lancons » (k).[/cadre]
[page]
[titre]-yer : y devient i[/titre]
Les verbes en [b]-oyer[/b] et [b]-uyer[/b] changent le y en [b]i[/b] devant un e muet.
[table=2][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=21]j'essu[b][color=#C62828]ie[/color][/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=21]nous essu[b][color=#C62828]y[/color][/b]ons[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=21]je netto[b][color=#C62828]ie[/color][/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=21]vous netto[b][color=#C62828]y[/color][/b]ez[/font_size][/center][/cell][/table]
[cadre=astuce]Avec balayer, on peut écrire [b]il balaye[/b] ou [b]il balaie[/b] : les deux sont justes.[/cadre]
[page]
[titre]Les verbes en -ier[/titre]
[cadre]colorier, trier, skier, planifier : je garde le [b]i[/b] du radical, puis la terminaison.
je colori[b]e[/b] · tu tri[b]es[/b] · nous ski[b]ons[/b] · ils planifi[b]ent[/b][/cadre]
[cadre=astuce]On entend à peine la terminaison, mais elle est bien là : je trie, nous trions.[/cadre]
[page]
[titre]Je retiens[/titre]
[cadre]• Verbes en -er : [b]e, es, e, ons, ez, ent[/b].
• tu → s ; ils, elles → ent (muet).
• être : suis, es, est, sommes, êtes, sont. avoir : ai, as, a, avons, avez, ont.
• nous plongeons, nous lançons. j'essuie, je nettoie.[/cadre]
$fiche$, 'publie', n.id from contenu_notions n where n.code = 'present'
on conflict (notion_id, classe) where statut <> 'archive'
do update set titre = excluded.titre, contenu = excluded.contenu, matiere = excluded.matiere, statut = 'publie', modifie_le = now()
returning id, classe, titre, statut;

-- Fiche Le présent : verbes en -ir et verbes irréguliers (CE2) - conjugaison, notion 'present'. Relancer ce script remplace le contenu de la fiche.
insert into contenu_cours (classe, matiere, titre, contenu, statut, notion_id)
select 'ce2', 'conjugaison', 'Le présent : verbes en -ir et verbes irréguliers', $fiche$
[titre]Les verbes comme finir[/titre]
Beaucoup de verbes en [b]-ir[/b] se conjuguent comme [b]finir[/b] (2e groupe).
[table=3][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][/color][/center][/cell][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]finir[/b][/color][/center][/cell][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]grandir[/b][/color][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20][b]je[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]fin[b][color=#C62828]is[/color][/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]grand[b][color=#C62828]is[/color][/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20][b]tu[/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20]fin[b][color=#C62828]is[/color][/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20]grand[b][color=#C62828]is[/color][/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20][b]il, elle[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]fin[b][color=#C62828]it[/color][/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]grand[b][color=#C62828]it[/color][/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20][b]nous[/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20]fin[b][color=#C62828]issons[/color][/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20]grand[b][color=#C62828]issons[/color][/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20][b]vous[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]fin[b][color=#C62828]issez[/color][/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]grand[b][color=#C62828]issez[/color][/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20][b]ils, elles[/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20]fin[b][color=#C62828]issent[/color][/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20]grand[b][color=#C62828]issent[/color][/b][/font_size][/center][/cell][/table]
[page]
[titre]Le reconnaître[/titre]
[cadre]Un verbe se conjugue comme finir si on dit « nous [b]…issons[/b] ».
nous chois[b]issons[/b] · nous roug[b]issons[/b] · nous applaud[b]issons[/b] ✓[/cadre]
[cadre=astuce]Pièges : il fini[b]t[/b] (et pas « il finis »), nous finissons (avec ss).[/cadre]
[page]
[titre]Aller et venir[/titre]
[table=3][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][/color][/center][/cell][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]aller[/b][/color][/center][/cell][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]venir[/b][/color][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20][b]je[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]vais[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]viens[/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20][b]tu[/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20]vas[/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20]viens[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20][b]il, elle[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]va[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]vient[/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20][b]nous[/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20]allons[/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20]venons[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20][b]vous[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]allez[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]venez[/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20][b]ils, elles[/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20]vont[/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20]viennent[/font_size][/center][/cell][/table]
[cadre]Ce ne sont pas des verbes comme finir : il faut les apprendre.[/cadre]
[page]
[titre]Faire et dire[/titre]
[table=3][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][/color][/center][/cell][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]faire[/b][/color][/center][/cell][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]dire[/b][/color][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20][b]je[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]fais[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]dis[/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20][b]tu[/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20]fais[/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20]dis[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20][b]il, elle[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]fait[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]dit[/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20][b]nous[/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20]faisons[/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20]disons[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20][b]vous[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]faites[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]dites[/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20][b]ils, elles[/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20]font[/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20]disent[/font_size][/center][/cell][/table]
[cadre=astuce]Attention : vous fai[b]tes[/b], vous di[b]tes[/b] (et pas « vous faisez »).[/cadre]
[page]
[titre]Rappel : les verbes en -er[/titre]
[cadre]je danse, tu danses, il danse, nous dansons, vous dansez, ils dansent.[/cadre]
[cadre=astuce]Ne pas confondre : « il fleuri[b]t[/b] » (finir) et « il danse » (-er) : les verbes en -ir prennent [b]-t[/b] avec il.[/cadre]
[page]
[titre]Je retiens[/titre]
[cadre]• Comme finir : is, is, it, issons, issez, issent.
• aller : vais, vas, va, allons, allez, vont.
• venir : viens, viens, vient, venons, venez, viennent.
• faire : fais, fais, fait, faisons, faites, font. dire : vous dites.[/cadre]
$fiche$, 'publie', n.id from contenu_notions n where n.code = 'present'
on conflict (notion_id, classe) where statut <> 'archive'
do update set titre = excluded.titre, contenu = excluded.contenu, matiere = excluded.matiere, statut = 'publie', modifie_le = now()
returning id, classe, titre, statut;

-- Fiche L'imparfait (CE2) - conjugaison, notion 'imparfait'. Relancer ce script remplace le contenu de la fiche.
insert into contenu_cours (classe, matiere, titre, contenu, statut, notion_id)
select 'ce2', 'conjugaison', 'L''imparfait', $fiche$
[titre]À quoi sert l'imparfait ?[/titre]
L'imparfait raconte ce qui se passait [b]avant[/b], ce qui [b]durait[/b] ou se [b]répétait[/b].
[cadre]Autrefois, mon grand-père [b]habitait[/b] à la campagne.
Chaque soir, il [b]rangeait[/b] ses outils.[/cadre]
[page]
[titre]Les terminaisons[/titre]
Pour [b]tous[/b] les verbes, les terminaisons sont les mêmes :
[table=3][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][/color][/center][/cell][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]parler[/b][/color][/center][/cell][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]finir[/b][/color][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20][b]je[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]parl[b][color=#C62828]ais[/color][/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]finiss[b][color=#C62828]ais[/color][/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20][b]tu[/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20]parl[b][color=#C62828]ais[/color][/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20]finiss[b][color=#C62828]ais[/color][/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20][b]il, elle[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]parl[b][color=#C62828]ait[/color][/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]finiss[b][color=#C62828]ait[/color][/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20][b]nous[/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20]parl[b][color=#C62828]ions[/color][/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20]finiss[b][color=#C62828]ions[/color][/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20][b]vous[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]parl[b][color=#C62828]iez[/color][/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]finiss[b][color=#C62828]iez[/color][/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20][b]ils, elles[/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20]parl[b][color=#C62828]aient[/color][/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20]finiss[b][color=#C62828]aient[/color][/b][/font_size][/center][/cell][/table]
[cadre][b]ais, ais, ait, ions, iez, aient[/b][/cadre]
[page]
[titre]Trouver le radical[/titre]
Je prends le verbe au présent avec [b]nous[/b], j'enlève -ons, et j'ajoute la terminaison.
[cadre]nous parl[b]ons[/b] → je parl[b]ais[/b]
nous finiss[b]ons[/b] → je finiss[b]ais[/b]
nous fais[b]ons[/b] → je fais[b]ais[/b][/cadre]
[page]
[titre]Être et avoir[/titre]
[table=3][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][/color][/center][/cell][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]être[/b][/color][/center][/cell][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]avoir[/b][/color][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20][b]je[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]j'ét[b][color=#C62828]ais[/color][/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]j'av[b][color=#C62828]ais[/color][/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20][b]tu[/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20]ét[b][color=#C62828]ais[/color][/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20]av[b][color=#C62828]ais[/color][/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20][b]il, elle[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]ét[b][color=#C62828]ait[/color][/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]av[b][color=#C62828]ait[/color][/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20][b]nous[/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20]ét[b][color=#C62828]ions[/color][/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20]av[b][color=#C62828]ions[/color][/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20][b]vous[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]ét[b][color=#C62828]iez[/color][/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]av[b][color=#C62828]iez[/color][/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20][b]ils, elles[/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20]ét[b][color=#C62828]aient[/color][/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20]av[b][color=#C62828]aient[/color][/b][/font_size][/center][/cell][/table]
[cadre=astuce]Être est la seule exception : on dit « nous sommes » mais « j'[b]ét[/b]ais ».[/cadre]
[page]
[titre]-cer et -ger[/titre]
[table=2][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]devant a : ç / ge[/b][/color][/center][/cell][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]devant i : c / g[/b][/color][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=19]je lan[b][color=#C62828]ç[/color][/b]ais, il pla[b][color=#C62828]ç[/color][/b]ait[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=19]nous lan[b][color=#C62828]c[/color][/b]ions, vous pla[b][color=#C62828]c[/color][/b]iez[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=19]je plon[b][color=#C62828]ge[/color][/b]ais, ils ran[b][color=#C62828]ge[/color][/b]aient[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=19]nous plon[b][color=#C62828]g[/color][/b]ions, vous plon[b][color=#C62828]g[/color][/b]iez[/font_size][/center][/cell][/table]
[cadre=astuce]Devant [b]a[/b] : ç et ge. Devant [b]i[/b] : c et g suffisent.[/cadre]
[page]
[titre]Je retiens[/titre]
[cadre]• Imparfait : [b]ais, ais, ait, ions, iez, aient[/b] pour tous les verbes.
• Radical = présent avec nous, sans -ons : nous faisons → je faisais.
• Être : j'étais. Avoir : j'avais.
• je lançais, il plongeait ; nous lancions, nous plongions.[/cadre]
$fiche$, 'publie', n.id from contenu_notions n where n.code = 'imparfait'
on conflict (notion_id, classe) where statut <> 'archive'
do update set titre = excluded.titre, contenu = excluded.contenu, matiere = excluded.matiere, statut = 'publie', modifie_le = now()
returning id, classe, titre, statut;

-- Fiche Le futur simple (CE2) - conjugaison, notion 'futur'. Relancer ce script remplace le contenu de la fiche.
insert into contenu_cours (classe, matiere, titre, contenu, statut, notion_id)
select 'ce2', 'conjugaison', 'Le futur simple', $fiche$
[titre]À quoi sert le futur ?[/titre]
Le futur dit ce qui [b]va se passer[/b] plus tard.
[cadre]Demain, je [b]visiterai[/b] le musée. L'an prochain, nous [b]camperons[/b] à la mer.[/cadre]
[page]
[titre]Infinitif + terminaison[/titre]
Pour les verbes en -er, je garde [b]tout l'infinitif[/b] et j'ajoute la terminaison.
[table=2][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][/color][/center][/cell][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]donner[/b][/color][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=22][b]je[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=22]donner[b][color=#C62828]ai[/color][/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=22][b]tu[/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=22]donner[b][color=#C62828]as[/color][/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=22][b]il, elle[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=22]donner[b][color=#C62828]a[/color][/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=22][b]nous[/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=22]donner[b][color=#C62828]ons[/color][/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=22][b]vous[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=22]donner[b][color=#C62828]ez[/color][/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=22][b]ils, elles[/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=22]donner[b][color=#C62828]ont[/color][/b][/font_size][/center][/cell][/table]
[cadre][b]ai, as, a, ons, ez, ont[/b] (comme le verbe avoir !)[/cadre]
[page]
[titre]Le e qu'on n'entend pas[/titre]
On ne l'entend presque pas, mais le [b]e[/b] de l'infinitif reste écrit.
[cadre]je compt[b]e[/b]rai · tu jou[b]e[/b]ras · nous colori[b]e[/b]rons · ils ski[b]e[/b]ront[/cadre]
[cadre=astuce]Je pense à l'infinitif entier : compter → compter + ai = je compterai.[/cadre]
[page]
[titre]Les verbes en -yer[/titre]
[table=2][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=19]nettoyer[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=19]je netto[b][color=#C62828]i[/color][/b]erai, ils netto[b][color=#C62828]i[/color][/b]eront[/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=19]essuyer[/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=19]tu essu[b][color=#C62828]i[/color][/b]eras[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=19]balayer[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=19]il balayera ou il balaiera (les deux sont justes)[/font_size][/center][/cell][/table]
[page]
[titre]Futur ou conditionnel ?[/titre]
[cadre]Au futur, avec je : [b]-ai[/b] → je donnerai.
Avec un [b]s[/b] (je donnerais), ce n'est plus le futur : c'est le conditionnel.[/cadre]
[cadre=astuce]Je remplace par « nous » : nous donnerons (futur) ✓.[/cadre]
[page]
[titre]Je retiens[/titre]
[cadre]• Futur des verbes en -er : infinitif + [b]ai, as, a, ons, ez, ont[/b].
• Le e de l'infinitif reste écrit : je jouerai, nous colorierons.
• -oyer / -uyer : i → je nettoierai, tu essuieras.
• Je : -ai (futur), pas -ais.[/cadre]
$fiche$, 'publie', n.id from contenu_notions n where n.code = 'futur'
on conflict (notion_id, classe) where statut <> 'archive'
do update set titre = excluded.titre, contenu = excluded.contenu, matiere = excluded.matiere, statut = 'publie', modifie_le = now()
returning id, classe, titre, statut;

-- Fiche Le présent : pouvoir, vouloir, savoir, voir, prendre (CM1) - conjugaison, notion 'present'. Relancer ce script remplace le contenu de la fiche.
insert into contenu_cours (classe, matiere, titre, contenu, statut, notion_id)
select 'cm1', 'conjugaison', 'Le présent : pouvoir, vouloir, savoir, voir, prendre', $fiche$
[titre]Pouvoir et vouloir[/titre]
[table=3][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][/color][/center][/cell][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]pouvoir[/b][/color][/center][/cell][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]vouloir[/b][/color][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20][b]je[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]peux[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]veux[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=20][b]tu[/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=20]peux[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=20]veux[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20][b]il, elle[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]peut[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]veut[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=20][b]nous[/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=20]pouvons[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=20]voulons[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20][b]vous[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]pouvez[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]voulez[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=20][b]ils, elles[/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=20]peuvent[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=20]veulent[/font_size][/center][/cell][/table]
[cadre=astuce]Avec je et tu : [b]x[/b] (je peux, tu veux). Avec il : [b]t[/b].[/cadre]
[page]
[titre]Savoir et voir[/titre]
[table=3][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][/color][/center][/cell][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]savoir[/b][/color][/center][/cell][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]voir[/b][/color][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20][b]je[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]sais[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]vois[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=20][b]tu[/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=20]sais[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=20]vois[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20][b]il, elle[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]sait[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]voit[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=20][b]nous[/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=20]savons[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=20]voyons[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20][b]vous[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]savez[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]voyez[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=20][b]ils, elles[/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=20]savent[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=20]voient[/font_size][/center][/cell][/table]
[cadre=astuce]nous vo[b]y[/b]ons, vous vo[b]y[/b]ez, mais ils vo[b]i[/b]ent.[/cadre]
[page]
[titre]Prendre[/titre]
[table=2][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][/color][/center][/cell][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]prendre[/b][/color][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=22][b]je[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=22]prends[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=22][b]tu[/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=22]prends[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=22][b]il, elle[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=22]prend[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=22][b]nous[/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=22]prenons[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=22][b]vous[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=22]prenez[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=22][b]ils, elles[/b][/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=22]prennent[/font_size][/center][/cell][/table]
[cadre=astuce]il pren[b]d[/b] (pas de t) ; ils pre[b]nn[/b]ent avec deux n. Pareil : apprendre, comprendre.[/cadre]
[page]
[titre]Ce qui revient souvent[/titre]
[cadre]• je, tu : terminaisons en [b]-s[/b] ou [b]-x[/b] : je sais, tu peux.
• il, elle : [b]-t[/b] ou [b]-d[/b] : il veut, il prend.
• ils, elles : [b]-ent[/b], souvent avec un radical qui change : ils peuvent, ils veulent.[/cadre]
[page]
[titre]Je retiens[/titre]
[cadre]• pouvoir : peux, peux, peut, pouvons, pouvez, peuvent.
• vouloir : veux, veux, veut, voulons, voulez, veulent.
• savoir : sais, sais, sait… ils savent. voir : vois… nous voyons, ils voient.
• prendre : prends, prends, prend, prenons, prenez, prennent.[/cadre]
$fiche$, 'publie', n.id from contenu_notions n where n.code = 'present'
on conflict (notion_id, classe) where statut <> 'archive'
do update set titre = excluded.titre, contenu = excluded.contenu, matiere = excluded.matiere, statut = 'publie', modifie_le = now()
returning id, classe, titre, statut;

