er][font_size=17]vivre[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=17]vécu[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=17]connaître[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=17]connu[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=17]être[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=17]été[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=17]avoir[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=17]eu[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=17]prendre[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=17]pris[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=17]mettre[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=17]mis[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=17]faire[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=17]fait[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=17]dire[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=17]dit[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=17]écrire[/font_size][/center][/cell][cell bg=#FFD49A border=#F2A541 padding=10,4,10,4][center][font_size=17]écrit[/font_size][/center][/cell][/table]
[page]
[titre]é ou er ?[/titre]
[cadre]Après avoir, c'est le participe : tu as ferm[b]é[/b] (et pas « tu as fermer »).[/cadre]
[cadre=astuce]Je remplace par un verbe en -re : « tu as [b]vendu[/b] » ✓ → participe → é.
« il va vendre » → infinitif → er.[/cadre]
[page]
[titre]La lettre muette du participe[/titre]
Pour savoir comment finit un participe, je le mets au [b]féminin[/b] :
[cadre]pri[b]s[/b] → prise · mi[b]s[/b] → mise · fai[b]t[/b] → faite · écri[b]t[/b] → écrite · di[b]t[/b] → dite[/cadre]
[page]
[titre]Je retiens[/titre]
[cadre]• Passé composé = avoir au présent + participe passé.
• -er → é ; comme finir → i ; attendre, perdre → u.
• À connaître : vu, lu, cru, bu, pu, voulu, su, dû, pris, mis, fait, dit, écrit, été, eu.
• Avec avoir, pas d'accord avec le sujet.[/cadre]
$fiche$, 'publie', n.id from contenu_notions n where n.code = 'passe_compose'
on conflict (notion_id, classe) where statut <> 'archive'
do update set titre = excluded.titre, contenu = excluded.contenu, matiere = excluded.matiere, statut = 'publie', modifie_le = now()
returning id, classe, titre, statut;

-- Fiche Le passé composé : avoir ou être ? (CM2) - conjugaison, notion 'passe_compose'. Relancer ce script remplace le contenu de la fiche.
insert into contenu_cours (classe, matiere, titre, contenu, statut, notion_id)
select 'cm2', 'conjugaison', 'Le passé composé : avoir ou être ?', $fiche$
[titre]Deux auxiliaires[/titre]
[cadre]Le passé composé = auxiliaire [b]avoir[/b] ou [b]être[/b] au présent + participe passé.
il [b]a[/b] vendu · tu [b]es[/b] resté[/cadre]
[page]
[titre]Les verbes avec être[/titre]
[table=4][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=19]aller[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=19]venir[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=19]arriver[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=19]partir[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=19]entrer[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=19]sortir[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=19]monter[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=19]descendre[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=19]naître[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=19]mourir[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=19]rester[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=19]tomber[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=19]devenir[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=19]revenir[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=19]retourner[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=19]passer (par)[/font_size][/center][/cell][/table]
[cadre=astuce]Tous les verbes pronominaux aussi : il [b]s'est[/b] levé.[/cadre]
[page]
[titre]Avec être, on accorde[/titre]
[table=2][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=21]Il est resté.[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=21]Elle est resté[b][color=#C62828]e[/color][/b].[/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=21]Ils sont resté[b][color=#C62828]s[/color][/b].[/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=21]Elles sont resté[b][color=#C62828]es[/color][/b].[/font_size][/center][/cell][/table]
[cadre]Avec avoir, jamais d'accord avec le sujet : elles ont vend[b]u[/b].[/cadre]
[page]
[titre]Des participes à connaître[/titre]
[table=4][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=19]construire[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=19]construit[/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=19]conduire[/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=19]conduit[/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=19]recevoir[/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=19]reçu[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=19]apercevoir[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=19]aperçu[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=19]acquérir[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=19]acquis[/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=19]ouvrir[/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=19]ouvert[/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=19]naître[/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=19]né[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=19]mourir[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=19]mort[/font_size][/center][/cell][/table]
[cadre=astuce]Lettre muette : je mets au féminin → construi[b]t[/b]e, ouver[b]t[/b]e.[/cadre]
[page]
[titre]Les pièges[/titre]
[cadre]• tu [b]as[/b] resté ✗ → tu [b]es[/b] resté ✓ (rester prend être)
• nous avons condui[b]s[/b] ✗ → nous avons condui[b]t[/b] ✓
• il a vendu[b]s[/b] ✗ → il a vendu ✓ (pas d'accord avec avoir)[/cadre]
[page]
[titre]Je retiens[/titre]
[cadre]• Avoir pour la plupart des verbes ; être pour aller, venir, rester, tomber… et les verbes pronominaux.
• Avec être : accord avec le sujet (elles sont restées).
• Avec avoir : pas d'accord avec le sujet.
• construit, conduit, reçu, ouvert : je vérifie la lettre muette au féminin.[/cadre]
$fiche$, 'publie', n.id from contenu_notions n where n.code = 'passe_compose'
on conflict (notion_id, classe) where statut <> 'archive'
do update set titre = excluded.titre, contenu = excluded.contenu, matiere = excluded.matiere, statut = 'publie', modifie_le = now()
returning id, classe, titre, statut;

-- Fiche Le plus-que-parfait (CM2) - conjugaison, notion 'plus_que_parfait'. Relancer ce script remplace le contenu de la fiche.
insert into contenu_cours (classe, matiere, titre, contenu, statut, notion_id)
select 'cm2', 'conjugaison', 'Le plus-que-parfait', $fiche$
[titre]Avant le passé[/titre]
Le plus-que-parfait raconte une action qui s'est passée [b]avant[/b] une autre action passée.
[cadre]Quand je suis arrivé, le train [b]était parti[/b].
→ le train est parti [b]d'abord[/b], puis je suis arrivé.[/cadre]
[page]
[titre]Comment le former[/titre]
Auxiliaire [b]avoir[/b] ou [b]être[/b] à l'[b]imparfait[/b] + participe passé.
[table=3][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][/color][/center][/cell][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]avoir[/b][/color][/center][/cell][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]être[/b][/color][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=18][b]je[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=18]j'avais joué[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=18]j'étais parti(e)[/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=18][b]tu[/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=18]avais joué[/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=18]étais parti(e)[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=18][b]il, elle[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=18]avait joué[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=18]était parti(e)[/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=18][b]nous[/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=18]avions joué[/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=18]étions parti(e)s[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=18][b]vous[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=18]aviez joué[/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=18]étiez parti(e)s[/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=18][b]ils, elles[/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=18]avaient joué[/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=18]étaient parti(e)s[/font_size][/center][/cell][/table]
[page]
[titre]Passé composé ou plus-que-parfait ?[/titre]
[cadre]Passé composé : auxiliaire au [b]présent[/b] → elles [b]ont[/b] joué.
Plus-que-parfait : auxiliaire à l'[b]imparfait[/b] → elles [b]avaient[/b] joué.[/cadre]
[cadre=astuce]Le participe ne change pas : seul l'auxiliaire change de temps.[/cadre]
[page]
[titre]Avec être, on accorde[/titre]
[cadre]Elle était arrivé[b]e[/b]. · Ils étaient venu[b]s[/b]. · Elles étaient né[b]es[/b] en mai.[/cadre]
[cadre=astuce]Les mêmes verbes qu'au passé composé prennent être : aller, venir, partir, naître, tomber, rester…[/cadre]
[page]
[titre]Le participe, pas l'infinitif[/titre]
[cadre]elles avaient pouss[b]é[/b] ✓ · elles avaient pousser ✗[/cadre]
[cadre=astuce]Je remplace par un verbe en -re : « elles avaient [b]vendu[/b] » → c'est un participe → é.[/cadre]
[page]
[titre]Je retiens[/titre]
[cadre]• Plus-que-parfait = avoir ou être à l'[b]imparfait[/b] + participe passé.
• Il dit ce qui s'est passé avant une autre action passée.
• Avec être : accord avec le sujet.
• Participe en -é, pas -er.[/cadre]
$fiche$, 'publie', n.id from contenu_notions n where n.code = 'plus_que_parfait'
on conflict (notion_id, classe) where statut <> 'archive'
do update set titre = excluded.titre, contenu = excluded.contenu, matiere = excluded.matiere, statut = 'publie', modifie_le = now()
returning id, classe, titre, statut;

-- Fiche Le conditionnel présent (CM2) - conjugaison, notion 'conditionnel'. Relancer ce script remplace le contenu de la fiche.
insert into contenu_cours (classe, matiere, titre, contenu, statut, notion_id)
select 'cm2', 'conjugaison', 'Le conditionnel présent', $fiche$
[titre]À quoi sert le conditionnel ?[/titre]
[cadre]• Un [b]souhait[/b] : J'aimerais voyager.
• Une demande [b]polie[/b] : Pourrais-tu m'aider ?
• Une action qui dépend d'une [b]condition[/b] : Si j'avais le temps, je [b]viendrais[/b].[/cadre]
[page]
[titre]Comment le former[/titre]
Radical du [b]futur[/b] + terminaisons de l'[b]imparfait[/b].
[table=3][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][/color][/center][/cell][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]chanter[/b][/color][/center][/cell][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]faire[/b][/color][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20][b]je[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]chanter[b][color=#C62828]ais[/color][/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]fer[b][color=#C62828]ais[/color][/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20][b]tu[/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20]chanter[b][color=#C62828]ais[/color][/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20]fer[b][color=#C62828]ais[/color][/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20][b]il, elle[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]chanter[b][color=#C62828]ait[/color][/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]fer[b][color=#C62828]ait[/color][/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20][b]nous[/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20]chanter[b][color=#C62828]ions[/color][/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20]fer[b][color=#C62828]ions[/color][/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20][b]vous[/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]chanter[b][color=#C62828]iez[/color][/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=20]fer[b][color=#C62828]iez[/color][/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20][b]ils, elles[/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20]chanter[b][color=#C62828]aient[/color][/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=20]fer[b][color=#C62828]aient[/color][/b][/font_size][/center][/cell][/table]
