[page]
[titre]venir et tenir : int, inrent[/titre]
[table=2][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]il, elle[/b][/color][/center][/cell][cell bg=#classe border=#classe padding=10,4,10,4][center][color=white][b]ils, elles[/b][/color][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=22]il v[b][color=#C62828]int[/color][/b][/font_size][/center][/cell][cell bg=#classe_clair border=#classe padding=10,4,10,4][center][font_size=22]ils v[b][color=#C62828]inrent[/color][/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=22]il t[b][color=#C62828]int[/color][/b][/font_size][/center][/cell][cell bg=#C6E2F8 border=#42A5F5 padding=10,4,10,4][center][font_size=22]ils t[b][color=#C62828]inrent[/color][/b][/font_size][/center][/cell][/table]
[cadre=astuce]Pas d'accent : il vint, ils vinrent.[/cadre]
[page]
[titre]Les pièges[/titre]
[cadre]• il regard[b]a[/b] (passé simple) ≠ il regard[b]ait[/b] (imparfait)
• il entend[b]it[/b] avec [b]t[/b] (pas « il entendis »)
• ils pass[b]èrent[/b] avec un accent grave[/cadre]
[page]
[titre]Je retiens[/titre]
[cadre]• -er : il chanta, ils chantèrent.
• finir, rendre, faire, prendre, voir : il finit, ils finirent.
• avoir, être, pouvoir, vouloir… : il eut, il fut, il put, ils purent.
• venir, tenir : il vint, ils vinrent.[/cadre]
$fiche$, 'publie', n.id from contenu_notions n where n.code = 'passe_simple'
on conflict (notion_id, classe) where statut <> 'archive'
do update set titre = excluded.titre, contenu = excluded.contenu, matiere = excluded.matiere, statut = 'publie', modifie_le = now()
returning id, classe, titre, statut;

commit;
